#include <metal_stdlib>
using namespace metal;

// Self-contained plush-heart scene for the Pipeline Editor's shader mode.
struct ShaderUniforms {
    float4 resolutionTime; // width, height, seconds, unused
    float4 mouse;          // reserved by the shared shader-state contract
};

float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}

float noise2(float2 p) {
    float2 cell = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash21(cell), hash21(cell + float2(1.0, 0.0)), f.x),
               mix(hash21(cell + float2(0.0, 1.0)),
                   hash21(cell + float2(1.0, 1.0)), f.x), f.y);
}

// The classic implicit heart gives two rounded lobes, a notch, and a pointed tip.
float heartDistance(float2 p) {
    float xx = p.x * p.x;
    float yy = p.y * p.y;
    float a = xx + yy - 1.0;
    float field = a * a * a - xx * p.y * yy;
    float2 gradient = float2(6.0 * p.x * a * a - 2.0 * p.x * p.y * yy,
                             6.0 * p.y * a * a - 3.0 * xx * yy);
    return field / max(length(gradient), 0.65);
}

float2 projectPoint(float3 point, float3 camera, float3 forward,
                    float3 right, float3 up, float focalLength) {
    float3 relative = point - camera;
    float depth = max(dot(relative, forward), 0.01);
    return float2(dot(relative, right), dot(relative, up))
           * (focalLength / depth);
}

float3 floorColor(float3 point) {
    float grain = noise2(point.xz * 8.0) - 0.5;
    float broad = exp(-0.016 * dot(point.xz, point.xz));
    return float3(0.75, 0.675, 0.565) + broad * float3(0.085, 0.075, 0.065)
           + grain * 0.013;
}

float3 renderHearts(float2 screen, float2 resolution, float time) {
    const float focalLength = 2.18;
    const float cycle = 8.4;
    float t = time - cycle * floor(time / cycle);

    float3 camera = float3(0.0, 3.9, -9.5);
    float3 forward = normalize(float3(0.0, 0.95, 0.0) - camera);
    float3 right = normalize(cross(float3(0.0, 1.0, 0.0), forward));
    float3 up = normalize(cross(forward, right));
    float3 ray = normalize(forward + (right * screen.x + up * screen.y)
                           / focalLength);

    // The floor continues to the horizon; a warm background fills the sky.
    float3 color = float3(0.91, 0.865, 0.78) - 0.035 * max(screen.y, 0.0);
    bool seesFloor = ray.y < -0.0001;
    float3 floorPoint = float3(0.0);
    if (seesFloor) {
        floorPoint = camera + ray * (-camera.y / ray.y);
        color = floorColor(floorPoint);
    }

    // Draw the five distant rows first so the nearer hearts sit in front.
    for (int i = 24; i >= 0; --i) {
        int row = i / 5;
        int column = i % 5;
        float index = float(i);
        float z = -3.8 + float(row) * 2.75;
        float size = 0.87 + float(row) * 0.065
                     + 0.06 * hash21(float2(index, 3.7));
        float screenColumn = (float(column) - 2.0) * 0.55
                             + (row % 2 == 1 ? 0.16 : 0.0);
        float nominalDepth = dot(float3(0.0, size, z) - camera, forward);
        float x = screenColumn * nominalDepth / focalLength
                  + 0.09 * sin(t * 1.34 + index * 1.8);

        // Each heart follows a parabolic bounce. At dropAt it keeps its
        // current height and velocity, then falls under gravity without
        // another bounce and settles on the floor.
        float bounceHeight = 1.28 + 0.30 * hash21(float2(index, 5.3));
        float bouncePeriod = 0.82 + 0.13 * hash21(float2(index, 7.1));
        float phaseOffset = hash21(float2(index, 9.4));
        float phase = fract(t / bouncePeriod + phaseOffset);
        float lift = 4.0 * bounceHeight * phase * (1.0 - phase);
        const float dropAt = 3.65;
        if (t >= dropAt) {
            float dropPhase = fract(dropAt / bouncePeriod + phaseOffset);
            float startHeight = 4.0 * bounceHeight * dropPhase
                                * (1.0 - dropPhase);
            float startVelocity = 4.0 * bounceHeight
                                  * (1.0 - 2.0 * dropPhase) / bouncePeriod;
            float fallTime = t - dropAt;
            lift = max(0.0, startHeight + startVelocity * fallTime
                             - 0.5 * 13.5 * fallTime * fallTime);
        }

        float vanishStart = 5.22 + float(row) * 0.10
                            + 0.24 * hash21(float2(index, 12.6));
        float vanish = smoothstep(vanishStart, vanishStart + 1.15, t);
        if (vanish >= 1.0) continue;
        float groundness = 1.0 - smoothstep(0.02, 0.20, lift);
        float stretchX = 1.0 + 0.10 * groundness;
        float stretchY = 1.0 - 0.12 * groundness;

        if (seesFloor) {
            float2 fromHeart = floorPoint.xz - float2(x, z);
            if (abs(fromHeart.x) < size * 2.5
                && abs(fromHeart.y) < size * 1.5) {
                float2 shadowPoint = fromHeart
                                     / float2(size * 0.9, size * 0.47);
                float shadow = exp(-dot(shadowPoint, shadowPoint) * 2.1);
                shadow *= (0.27 / (1.0 + lift * 0.9)) * (1.0 - vanish);
                color *= 1.0 - shadow;
            }
        }

        float3 center = float3(x, size * 1.02 * stretchY + lift, z);
        float3 relative = center - camera;
        float depth = max(dot(relative, forward), 0.01);
        float pixelsPerUnit = focalLength / depth;
        float2 centerScreen = projectPoint(center, camera, forward, right,
                                           up, focalLength);
        float2 p = (screen - centerScreen) / (pixelsPerUnit * size);
        p.x /= stretchX;
        p.y /= stretchY;
        float baseTilt = (hash21(float2(index, 11.7)) - 0.5) * 0.30;
        float wobble = 0.10 * sin(t * 5.2 + index * 1.2)
                       * smoothstep(0.0, 0.45, lift);
        float angle = baseTilt + wobble;
        float cosine = cos(angle);
        float sine = sin(angle);
        p = float2(cosine * p.x + sine * p.y,
                   -sine * p.x + cosine * p.y);

        if (abs(p.x) > 1.55 || abs(p.y) > 1.65) continue;

        float distance = heartDistance(p);
        float2 seed = float2(index * 17.0, index * 29.0);
        float fur = (noise2(p * 64.0 + seed) - 0.5) * 0.047
                  + (noise2(p * 154.0 + seed) - 0.5) * 0.015;
        float pixelWidth = 2.0 / (resolution.y * pixelsPerUnit * size);
        float alpha = 1.0 - smoothstep(-pixelWidth, pixelWidth,
                                        distance + fur);

        // Small strands catch the light while the outer silhouette stays soft.
        float fiber = noise2(p * float2(96.0, 138.0) + seed);
        float strands = 0.5 + 0.5 * sin(p.x * 190.0 + p.y * 52.0
                                        + noise2(p * 15.0 + seed) * 8.0);
        float bulge = smoothstep(0.0, 0.39, -distance);
        float sideLight = clamp(0.5 - 0.22 * p.x + 0.28 * p.y, 0.0, 1.0);
        float light = 0.62 + 0.19 * bulge + 0.22 * sideLight;
        float3 red = float3(0.72, 0.055, 0.073)
                     * (0.88 + 0.20 * hash21(float2(index, 53.9)));
        float3 heartColor = red * light * (0.82 + 0.27 * fiber
                                          + 0.075 * strands);
        float rim = exp(-pow(max(-distance, 0.0) / 0.075, 2.0));
        heartColor += float3(0.16, 0.045, 0.04) * rim
                      * (0.4 + 0.6 * sideLight);
        float glint = exp(-dot((p - float2(-0.42, 0.58))
                               / float2(0.31, 0.25),
                               (p - float2(-0.42, 0.58))
                               / float2(0.31, 0.25)) * 1.9);
        heartColor += float3(0.11, 0.035, 0.036) * glint;

        // Individual tufts fade at different times, then a few loose fibers
        // drift outward before the floor is left empty for the next cycle.
        if (vanish > 0.0) {
            float tuft = hash21(floor(p * 77.0) + seed);
            alpha *= smoothstep(vanish - 0.035, vanish + 0.035, tuft);
            alpha *= 1.0 - vanish * 0.25;
            float2 fleckPoint = (p - float2(0.12, 0.28) * vanish)
                                * 34.0;
            float2 fleckCell = floor(fleckPoint);
            float fleckChance = hash21(fleckCell + seed * 2.0);
            float fleck = 1.0 - smoothstep(0.12, 0.36,
                                           length(fract(fleckPoint) - 0.5));
            fleck *= step(0.978, fleckChance)
                     * sin(vanish * 3.14159265)
                     * (1.0 - smoothstep(1.0, 1.75, length(p)));
            heartColor = mix(heartColor, float3(0.87, 0.24, 0.22), fleck);
            alpha = max(alpha, fleck * 0.55);
        }
        color = mix(color, heartColor, clamp(alpha, 0.0, 1.0));
    }

    // The shader contract expects opaque display-referred sRGB output.
    return clamp(color, float3(0.0), float3(1.0));
}

vertex float4 fullscreenVertex(uint vertexID [[vertex_id]]) {
    float2 p = float2((vertexID << 1) & 2, vertexID & 2);
    return float4(p * 2.0 - 1.0, 0.0, 1.0);
}

fragment float4 furryHeartsFragment(
    float4 position [[position]], constant ShaderUniforms &uniforms [[buffer(0)]]) {
    float2 resolution = uniforms.resolutionTime.xy;
    float2 frag = float2(position.x, resolution.y - position.y);
    float2 screen = (frag - 0.5 * resolution) * (2.0 / resolution.y);
    return float4(renderHearts(screen, resolution, uniforms.resolutionTime.z),
                  1.0);
}
